// proposed (A): <> is the value from the line above.
// Prints the same six lines as today's named version (probe t02_today_full).

fn app_port(raw: [U8], fallback: Int) -> Int {
    raw
        |> String.from_bytes(<>) ?? return fallback        // each step has its own fallback
        |> Int.parse(<>.trim()) ?? return fallback
        |> if <> < 1 || <> > 65535 -> fallback else -> <>   // <> may repeat in a step
}

// A pipe inside a lambda: there <> is that pipe's own value.
fn total(lines: [String]) -> Int {
    lines.map(fn(line) { line |> Int.parse(<>.trim()) ?? 0 }).sum()
}

// A lambda inside a step captures that step's <>.
fn scaled(values: [Int], factor_text: String) -> [Int] {
    factor_text
        |> Int.parse(<>.trim()) ?? return values
        |> values.map(fn(v) { v * <> })
}

fn clamp(n: Int, low: Int, high: Int) -> Int {
    if n < low -> low else if n > high -> high else -> n
}

fn label(name: String, size: Int) -> String {
    "{name}#{size}"
}

// A nested pipe: its first line reads the outer <>, its step sees its own.
fn badge(raw: [U8]) -> String {
    raw
        |> String.from_bytes(<>) ?? return "?"
        |> label(<>.trim(), (<>.len() |> clamp(<>, 0, 9)))
}

// <> means nothing else in Jet. These keep their meaning:
//   a < b, a <= b, a <=> b, 1 << 2, Box<Int>, <: 1, 2 :>
// These become errors with fixes:
//   a <> b            -> write a != b
//   <>>2              -> write <> >> 2 or <> > 2 (space after <>)
//   Box<>{value: 1}   -> write Box<Int>{value: 1}

fn run() {
    print(app_port([U8]{" 8080 "}, 80))     // 8080
    print(app_port([U8]{"http"}, 80))       // 80
    print(total([" 1", "2 ", "x"]))         // 3
    print(scaled([1, 2, 3], " 10"))         // [10, 20, 30]
    print(scaled([1, 2, 3], "ten"))         // [1, 2, 3]
    print(badge([U8]{" hi "}))              // hi#4
}

