// package.jet
authority: { holds: { allow: [Meta.Code] } }

// @build.jet: the application's own source makes the value
fn build(b: Build) {
    app :: b.add_executable("app", find("Source/**/*.jet"))
    meta :: b.compiler(app)                // one value for the program app
    trace.install(meta, marked: Traced)    // Traced is the marker written #Traced
    profile.install(meta, marked: Hot)     // registered second, so it wraps outside trace
    b.default(app)
}   // compiling starts after fn build returns; the handlers run then

// trace library: ordinary Jet; events() registers a handler and returns at once
fn install(meta: Compiler, marked: Marker) {
    meta.events(watch: .Functions(marked: marked), (event) -> {
        // == against a pattern tests the event and binds f
        if event == .Checked(.Function(f)) -> {
            name :: f.name
            body :: f.body                 // the current body, after earlier rewrites
            meta.rewrite_body(f, #code {
                trace.enter($name)
                defer trace.exit($name)    // defer: runs when the function exits
                $body
            })
        }
    })
}

// a dependency handed the root's b still cannot make one
fn add_step(b: Build, out: Output) { meta :: b.compiler(out) }
// error: `b.compiler` must be written in the application's own source; package shaders cannot create a Compiler value
