// Beginner engine code: one line.
fn edit<T: Patchable>(value: &T, path: String, text: String) PatchError! {
    value = value.apply(value.parse_patch(path, text))   // a failure says why
}

// Expert: keep an undo patch, the old values of the changed fields.
fn edit_undoable<T: Patchable>(value: &T, path: String, text: String) -> T.Patch PatchError! {
    before :: value.copy()
    edit(&value, path, text)
    Ok(T.diff(^before, value.copy()))
}

