// package engine
trait Edit { fn set(&self, field: String, text: String) -> Bool }

struct Entity {
    impl Marker {
        sites :: [.Type]
        fn expand(self, target: Target) {
            impl #{target}.Edit {
                fn set(&self, field: String, text: String) -> Bool {
                    loop f in target.fields {
                        if field == f.name -> {
                            self.#{f} = #{f.ty}.parse(text) ?? return false
                            return true
                        }
                    }
                    false
                }
            }
        }
    }
}

fn edit<T: Edit>(value: &T, field: String, text: String) -> Bool {
    value.set(field, text)
}

