// package graph
use core.db.[DBValue]

#Error
enum CypherError { Empty NoReturn }

struct Cypher {
    text: String
    values: [DBValue]
}

impl Cypher.CheckedText {
    type Error = CypherError
    type Hole = DBValue                                  // new optional member

    // sees "MATCH (p:Person) WHERE p.age > {} RETURN p" while compiling
    fn check(text: String) CypherError! -[]> {
        if text == "" -> return Err(CypherError.Empty)
        if !text.contains("RETURN") -> return Err(CypherError.NoReturn)
    }

    fn encode_hole<T: Printable>(value: T) -[]> DBValue { DBValue.of(value) }

    // new optional member; the default joins parts and holes into text
    fn build(parts: [String], holes: ^[DBValue]) -[]> Self {
        text := parts[0].copy()
        loop i in 0..<holes.len() -> text = "{text}$p{i}{parts[i + 1]}"
        Cypher{text: text, values: ^holes}
    }
}

// a text-only kind is unchanged: no Hole, no build
impl Label.CheckedText {
    type Error = LabelError
    fn check(text: String) LabelError! -[]> { label_grammar(text) }
    fn encode_hole<T: Printable>(value: T) -[]> String { escape("{value}") }
}

